// Provided infrastructure — do not modify.
// Legacy.Price IS the behavior you must preserve, then extend with "vip".
// It is deliberately smelly: magic numbers, nested conditionals, duplication.
public static class Legacy
{
    public static decimal Price(int qty, decimal unit, string tier)
    {
        decimal total = qty * unit;
        decimal d = 0m;
        if (tier == "gold")
        {
            if (qty >= 10) d = 0.20m; else d = 0.10m;
        }
        else if (tier == "silver")
        {
            if (qty >= 10) d = 0.10m; else d = 0.05m;
        }
        if (qty > 100) d += 0.02m;
        return total * (1m - d);
    }
}

